{
  "openapi": "3.1.0",
  "info": {
    "title": "Modulr API",
    "description": "Modulr API",
    "license": {
      "name": "© Modulr Finance",
      "url": "https://www.modulrfinance.com"
    },
    "version": "1.0"
  },
  "servers": [
    {
      "url": "https://api-sandbox.modulrfinance.com/api-sandbox-token"
    }
  ],
  "security": [
    {
      "modulo_security": []
    }
  ],
  "tags": [
    {
      "name": "Access Group",
      "description": "Operations on Access Group"
    }
  ],
  "paths": {
    "/access-groups/{accessGroupId}": {
      "get": {
        "tags": [
          "Access Group"
        ],
        "summary": "Get access group",
        "description": "The ability to retrieve an access group by ID",
        "operationId": "getAccessGroup",
        "parameters": [
          {
            "name": "accessGroupId",
            "in": "path",
            "description": "Access group ID",
            "required": true,
            "style": "simple",
            "explode": false,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/account.AccessGroupWithDetailsResponse"
                }
              }
            }
          },
          "400": {
            "description": "Bad Request",
            "content": {
              "*/*": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/account.MessageResponse"
                  }
                }
              }
            }
          }
        },
        "security": [
          {
            "HMAC": []
          },
          {
            "TOKEN": []
          }
        ]
      }
    }
  },
  "components": {
    "schemas": {
      "account.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
          },
          "code": {
            "type": "string",
            "enum": [
              "GENERAL",
              "BUSINESSRULE",
              "MFASTATUS",
              "MFAERROR",
              "MFATIMEOUT",
              "MFADEVICEMM",
              "MFAMESSAGEINVALID",
              "NOTFOUND",
              "DUPLICATE",
              "INVALID",
              "CONNECTION",
              "RETRY",
              "RATELIMIT",
              "PERMISSION",
              "NOTACCEPTABLE",
              "MFAVERIFICATION",
              "TOKENEXPIRED"
            ]
          },
          "errorCode": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "sourceService": {
            "type": "string"
          }
        }
      },
      "account.AccessGroupWithDetailsResponse": {
        "type": "object",
        "description": "AccessGroupWithDetails",
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique ID for the access group",
            "example": "G0000001"
          },
          "name": {
            "type": "string",
            "description": "Access group name"
          },
          "type": {
            "type": "string",
            "description": "The type of access group",
            "enum": [
              "SERVICE_PARTNER",
              "SERVICE_CUSTOMER",
              "DELEGATE",
              "USER_DEFINED"
            ]
          },
          "typeId": {
            "type": "string",
            "description": "The identifier of the linked entity implied by the type, e.g. the partner ID"
          },
          "status": {
            "type": "string",
            "description": "Status of the access group",
            "enum": [
              "ACTIVE",
              "DELETED"
            ]
          },
          "countOfAccounts": {
            "type": "integer",
            "format": "int64",
            "deprecated": true,
            "description": "The number of accounts in this group"
          },
          "accountIds": {
            "type": "array",
            "description": "BIDs of Accounts in the group",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          },
          "beneficiaryIds": {
            "type": "array",
            "description": "BIDs of Beneficiaries in the group",
            "items": {
              "type": "string"
            },
            "uniqueItems": true
          }
        }
      }
    },
    "securitySchemes": {
      "modulo_security": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      },
      "TOKEN": {
        "type": "apiKey",
        "name": "Authorization",
        "in": "header"
      }
    }
  },
  "x-readme": {
    "proxy-enabled": false
  }
}
